### Step 3: Add `extract_flags` in dart.rs

Import the flag constants from the Rust parser module and implement Dart-specific flag extraction:

```rust
use super::rust::{FLAG_TEST, FLAG_CFG_TEST, FLAG_FFI_ENTRY};

fn extract_flags(node: Node, src: &[u8], file_path: &str) -> u32 {
    let mut flags = 0u32;

    // @isTest, @isTestGroup, @Test annotations → FLAG_TEST
    if has_annotation(node, src, \"isTest\")
        || has_annotation(node, src, \"isTestGroup\")
        || has_annotation(node, src, \"Test\")
    {
        flags |= FLAG_TEST;
    }

    // Test file patterns → FLAG_CFG_TEST
    if file_path.ends_with(\"_test.dart\") || file_path.starts_with(\"test/\") {
        flags |= FLAG_CFG_TEST;
    }

    // @override → FLAG_FFI_ENTRY (framework entry point, suppresses dead-code)
    if has_annotation(node, src, \"override\") {
        flags |= FLAG_FFI_ENTRY;
    }

    // @pragma('vm:entry-point') → FLAG_FFI_ENTRY
    if has_annotation(node, src, \"pragma\") {
        // Check if it's specifically vm:entry-point
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            if child.kind() == \"annotation\" {
                if let Ok(text) = child.utf8_text(src) {
                    if text.contains(\"vm:entry-point\") {
                        flags |= FLAG_FFI_ENTRY;
                    }
                }
            }
        }
    }

    flags
}
```

Note: `file_path` is added as a parameter (unlike Rust's version) because Dart test detection relies partly on file paths, not just annotations. This is acceptable since `file_path` is available at the call site in `parse()`.

