    String get name => 'test';
    set name(String v) {}
}
\"#;
    let result = parser::parse_file(src, \"dart\", \"lib/config.dart\").unwrap();
    let flat = flatten_symbols(&result.symbols);

    let getter = flat.iter().find(|s| s.short_name == \"name\" && /* is_getter check */).unwrap();
    let attrs: serde_json::Value = serde_json::from_str(getter.language_attrs.as_deref().unwrap()).unwrap();
